"""Produces a single-file, interactive quiz-studio replay from saved events.
No AI-generated imagery; browser renders SVG/CSS directly from recorded decisions.
"""
from pathlib import Path
import argparse,json,html
TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Millionaire of Uncertainty — Measured Agent Replay</title>
<style>
:root{--bg:#07172c;--panel:#101f37;--line:#3b5475;--gold:#f4c96b;--muted:#a4b7d2;--white:#f5f8ff;--green:#5ce0a5;--red:#f4818f}*{box-sizing:border-box}body{margin:0;background:#071121;color:var(--white);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;min-width:810px}header{background:#0c1b30;border-bottom:1px solid #2b435f;padding:15px 25px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:23px;font-weight:800;letter-spacing:.7px}.brand em{font-style:normal;color:var(--gold)}.micro{color:#99acc7;font-size:12px}.wrap{max-width:1350px;margin:auto;padding:20px 23px}.agents{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:15px}.agent{background:#111f36;border:1px solid #314867;border-radius:12px;padding:10px;cursor:pointer;color:#e8edf9;text-align:left}.agent.active{border:2px solid var(--gold);background:#253047}.avatar{width:24px;height:24px;border-radius:50%;display:inline-grid;place-items:center;background:#344966;color:var(--gold);font-weight:700;margin-right:8px}.agent strong{font-size:13px}.agent small{display:block;color:#b8c5d9;margin:3px 0 0 34px}.main{display:grid;grid-template-columns:minmax(0,2.3fr) minmax(255px,.8fr);gap:15px}.stage{border:1px solid #34506b;border-radius:18px;background:radial-gradient(ellipse at 55% 0,#1c3260,#0a1630 57%);min-height:560px;position:relative;overflow:hidden;padding:26px 32px;box-shadow:inset 0 0 40px #021127}.spots{display:flex;justify-content:space-between;position:absolute;top:0;left:0;right:0;pointer-events:none}.beam{height:170px;width:30%;background:linear-gradient(to bottom,#e2b65770,transparent);clip-path:polygon(30% 0,70% 0,100% 100%,0 100%);opacity:.2}.badge{display:inline-block;border:1px solid #6c769a;color:#cee0fa;font-size:11px;font-weight:700;letter-spacing:1.3px;padding:6px 11px;border-radius:20px}.level{color:#f5cd76;font-size:13px;letter-spacing:2px;margin-top:30px;font-weight:700}.question{font-size:24px;line-height:1.35;min-height:82px;max-width:730px;margin:12px auto 18px;text-align:center;font-weight:700}.options{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;min-height:144px}.option{background:#122445d9;border:2px solid #425e8c;border-radius:9px;padding:15px 13px;font-weight:600;transition:.25s}.option .letter{color:var(--gold);margin-right:12px}.option.picked{border-color:#ffd47d;background:#5e482a}.option.good{border-color:var(--green);background:#114a40}.option.bad{border-color:var(--red);background:#62313b}.option.removed{opacity:.20;text-decoration:line-through}.info{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:22px}.info>div{background:#09182d9c;border:1px solid #253c57;padding:12px;border-radius:10px}.info label{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:1px}.info strong{display:block;margin-top:4px;font-size:19px}.reason{border-top:1px solid #2d4668;padding-top:14px;margin-top:14px;color:#e6ecf6;min-height:76px}.decision{font-size:19px;font-weight:800;color:var(--gold)}.pill{background:#32435a;border-radius:20px;padding:3px 10px;display:inline-block;margin-right:4px;font-size:11px}.pill.used{opacity:.32}.side{background:#0d1c34;border:1px solid #30435c;border-radius:16px;padding:15px;display:flex;flex-direction:column}.side h3{margin:0 0 10px;color:#bfcbe1;font-size:14px}.prize{display:flex;justify-content:space-between;border-radius:6px;padding:4px 9px;font-size:13px;color:#a5bed5}.prize.safe{color:#e6c378}.prize.active{background:#415071;color:#fff;border:1px solid #f5c873}.prize.complete{color:#65dbb4}.poll{margin-top:12px;border-top:1px solid #354e69;padding-top:12px;min-height:113px}.pollrow{display:flex;align-items:center;gap:5px;font-size:12px;margin:5px 0}.pollbar{height:11px;border-radius:4px;background:#ddba73}.barback{flex:1;background:#344a66;height:11px;border-radius:4px}.controls{display:flex;gap:10px;align-items:center;margin-top:15px}.controls button{border:1px solid #8aa0b9;color:#fff;background:#203755;border-radius:9px;padding:10px 20px;cursor:pointer}.controls button.primary{border-color:#edc06a;color:#17213d;background:#f4ca78;font-weight:800}.controls input{flex:1;accent-color:#efc46e}.log{background:#0d1d33;border:1px solid #284460;border-radius:13px;margin-top:14px;padding:12px;font-size:12px;color:#bac8db}.log h4{font-size:12px;margin:0 0 7px;letter-spacing:1px}.logline{border-top:1px solid #2a3f5e;padding:6px 0}.foot{text-align:center;color:#8299b8;font-size:11px;padding:12px}.verdict{font-size:11px;border:1px solid #556d8f;border-radius:100px;padding:4px 9px;margin-left:8px}
</style></head><body>
<header><div class="brand">THE <em>MILLIONAIRE</em> TEST <span class="verdict">SIMULATED POLICY AGENTS</span></div><div class="micro">Actual recorded actions • 15 questions • 3 lifelines • Paired evidence</div></header>
<div class="wrap"><div class="agents" id="agents"></div><div class="main"><div class="stage"><div class="spots"><div class="beam"></div><div class="beam"></div><div class="beam"></div></div><span class="badge" id="status">REPLAY · PAUSED</span><div class="level" id="level">QUESTION 01 · $100</div><div class="question" id="question"></div><div class="options" id="options"></div><div class="info"><div><label>Agent's estimated confidence</label><strong id="confidence"></strong></div><div><label>Guaranteed if wrong</label><strong id="guaranteed"></strong></div><div><label>Banked prize</label><strong id="banked"></strong></div></div><div class="reason"><span class="decision" id="decision"></span><div id="reason"></div></div><div id="lifelines" style="margin-top:12px"></div></div>
<div class="side"><h3>THE MONEY LADDER</h3><div id="ladder"></div><div class="poll" id="poll"></div></div></div>
<div class="controls"><button class="primary" id="play">▶ Play</button><button id="back">◀ Back</button><button id="next">Next ▶</button><input aria-label="Replay step" type="range" min="0" id="seek" value="0"><span id="step"></span></div><div class="log"><h4>RECORDED ACTIONS — NO HIDDEN CHAIN-OF-THOUGHT</h4><div id="log"></div></div><div class="foot">Controlled AI decision policies share one synthetic answer engine. On-screen confidence and reasons come from saved policy events, not live commercial LLM inference.</div></div>
<script>const DATA=__DATA__;const MONEY=[100,200,300,500,1000,2000,4000,8000,16000,32000,64000,125000,250000,500000,1000000];let who=5,at=0,timer=null;const $=s=>document.getElementById(s),fmt=n=>'$'+Math.round(n).toLocaleString('en-US');function player(){return DATA.players[who]}function cur(){return player().events[Math.min(at,player().events.length-1)]}function render(){let e=cur(),p=player();$('agents').innerHTML=DATA.players.map((x,i)=>`<button class="agent ${i===who?'active':''}" onclick="pick(${i})"><span class="avatar">${x.name[0]}</span><strong>${x.name}</strong><small>${fmt(x.final)} · ${x.status}</small></button>`).join('');$('level').textContent=`QUESTION ${String(e.question_number).padStart(2,'0')} · ${fmt(e.amount)}`;$('question').textContent=e.question;$('confidence').textContent=Math.round(e.estimated_confidence*100)+'%';$('guaranteed').textContent=fmt(e.safe_before);$('banked').textContent=fmt(e.won_before);$('decision').textContent=e.action==='50:50'?'50:50 CALLED':e.action==='AUDIENCE'?'ASK THE AUDIENCE':e.action==='FRIEND'?'PHONE A FRIEND':e.action==='WALK'?'WALKS AWAY':e.result==='WRONG'?'WRONG ANSWER':e.result==='CORRECT'?'CORRECT ANSWER':'ANSWER';$('decision').style.color=e.result==='WRONG'?'#ff93a7':e.result==='CORRECT'?'#61e6b8':'#f4c96b';$('reason').textContent=e.reason+(e.result==='WALK'?' — Keeps '+fmt(e.paid):e.result==='WRONG'?' — Falls back to '+fmt(e.paid):'');let remove=e.action==='50:50'?e.help.removed:[];let picked=e.choice;let answer=e.correct_index;$('options').innerHTML=e.options.map((o,i)=>{let clazz=remove.includes(i)?'removed':'';if((e.result==='WRONG'||e.result==='CORRECT')&&i===picked)clazz+=' '+(e.result==='CORRECT'?'good':'bad');if((e.result==='WRONG')&&i===answer)clazz+=' good';return `<div class="option ${clazz}"><span class="letter">${'ABCD'[i]}:</span>${escapeHtml(o)}</div>`}).join('');$('lifelines').innerHTML=['50:50','AUDIENCE','FRIEND'].map(x=>`<span class="pill ${e.lifelines_remaining.includes(x)?'':'used'}">${x==='FRIEND'?'☎ Friend':x==='AUDIENCE'?'▥ Audience':'50:50'}</span>`).join('');$('poll').innerHTML=e.action==='AUDIENCE'?'<h3>LIVE AUDIENCE VOTE</h3>'+e.help.counts.map((n,i)=>`<div class="pollrow"><span>${'ABCD'[i]}</span><div class="barback"><div class="pollbar" style="width:${n*2.5}%"></div></div><b>${n}%</b></div>`).join('').replaceAll('%</b>', ' / 40</b>'):e.action==='FRIEND'?`<h3>PHONE A FRIEND</h3>Friend suggests ${'ABCD'[e.help.suggested_index]}. Advice is fallible.`:e.action==='50:50'?'<h3>50:50</h3>Two wrong options removed.': '<h3>STUDIO STATUS</h3>Waiting for the next recorded decision.';$('ladder').innerHTML=MONEY.map((x,k)=>{return `<div class="prize ${[4,9,14].includes(k)?'safe':''} ${k===e.question_number-1?'active':''} ${k<e.question_number-1?'complete':''}"><span>${String(k+1).padStart(2,'0')}</span><b>${fmt(x)}</b></div>`}).reverse().join('');$('step').textContent=(at+1)+' / '+p.events.length;$('seek').max=Math.max(0,p.events.length-1);$('seek').value=at;$('log').innerHTML=p.events.slice(Math.max(0,at-4),at+1).map(x=>`<div class="logline">Q${x.question_number} · ${x.action} · ${Math.round(x.estimated_confidence*100)}% ${x.result?'· '+x.result:''}</div>`).join('');}
function escapeHtml(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')};function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='▶ Play'}function pick(i){stop();who=i;at=0;render()}function step(d){let n=player().events.length;at=Math.min(n-1,Math.max(0,at+d));render();if(at===n-1)stop()}$('play').onclick=()=>{if(timer){stop();return}if(at>=player().events.length-1)at=0;timer=setInterval(()=>step(1),850);$('play').textContent='Ⅱ Pause'};$('next').onclick=()=>{stop();step(1)};$('back').onclick=()=>{stop();step(-1)};$('seek').oninput=e=>{stop();at=Number(e.target.value);render()};window.pick=pick;window.go=(a,s)=>{stop();who=a;at=s;render()};render();</script></body></html>'''

def main():
 a=argparse.ArgumentParser();a.add_argument('--featured',default='results/featured.json');a.add_argument('--output',default='viewer/millionaire_replay.html');args=a.parse_args()
 data=json.loads(Path(args.featured).read_text(encoding='utf8'))
 out=Path(args.output);out.parent.mkdir(parents=True,exist_ok=True)
 out.write_text(TEMPLATE.replace('__DATA__',json.dumps({'seed':data['seed'],'players':data['players']},ensure_ascii=False).replace('</','<\\/')),encoding='utf8')
 print('Built',out,round(out.stat().st_size/1024),'KB')
if __name__=='__main__':main()
